arguments.command:
cat > tests/prune_test.sh <<'EOF'
#!/bin/bash
# prune: audit logs live under var/audit and are kept 400 days (ADR-0015).
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
mkdir -p "$d/var/audit" "$d/var/log/audit"
touch -d '401 days ago' "$d/var/audit/old.log" "$d/var/log/audit/wrong-place.log"
touch -d '399 days ago' "$d/var/audit/recent.log"
touch -d '100 days ago' "$d/var/audit/mid.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run)
[ "$out" = "$d/var/audit/old.log" ] || { echo "prune dry-run list: $out"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ -e "$d/var/audit/old.log" ] && { echo "prune kept old audit log"; fail=1; }
[ -e "$d/var/audit/recent.log" ] && [ -e "$d/var/audit/mid.log" ] || { echo "prune removed log within retention"; fail=1; }
[ -e "$d/var/log/audit/wrong-place.log" ] || { echo "prune touched var/log"; fail=1; }
rm -rf "$d"
exit $fail
EOF
bash tests/prune_test.sh; echo $?

